function explain(kind, value) {
  const i = Math.max(1, Math.min(5, Number(value || 3))) - 1;
  const data = {
    influence: ["Sehr geringer Einfluss: wirkt kaum auf Entscheidung oder Gruppendynamik.", "Geringer Einfluss: wird gehört, prägt aber nur begrenzt.", "Mittlerer Einfluss: kann Stimmungen oder Entscheidungen mitprägen.", "Hoher Einfluss: prägt Akzeptanz, Tempo oder Widerstand deutlich.", "Sehr hoher Einfluss: Schlüsselrolle; ohne diese Rolle kippt das Szenario leicht."],
    affectedness: ["Sehr geringe Betroffenheit: nur randständig berührt.", "Geringe Betroffenheit: Auswirkungen sind vorhanden, aber begrenzt.", "Mittlere Betroffenheit: spürbare Veränderung im Alltag.", "Hohe Betroffenheit: Rolle, Verantwortung oder Routinen sind stark betroffen.", "Sehr hohe Betroffenheit: Veränderung berührt Selbstverständnis oder Arbeitsweise zentral."],
    trust: ["Sehr geringes Vertrauen: starke Schutz- oder Abwehrlogik wahrscheinlich.", "Geringes Vertrauen: Kommunikation muss zuerst Sicherheit erzeugen.", "Mittleres Vertrauen: Zustimmung hängt stark von Transparenz ab.", "Hohes Vertrauen: konstruktive Mitarbeit möglich, wenn Grenzen klar sind.", "Sehr hohes Vertrauen: stabilisierende oder multiplizierende Rolle."],
    aiLiteracy: ["Sehr geringe KI-Kompetenz: Grundlagen und Grenzen zuerst klären.", "Geringe KI-Kompetenz: einfache Beispiele und sichere Anleitung nötig.", "Mittlere KI-Kompetenz: Anwendung möglich, Begleitung bleibt wichtig.", "Hohe KI-Kompetenz: kann Use Cases entwickeln und andere unterstützen.", "Sehr hohe KI-Kompetenz: mögliche Multiplikator- oder Pilotrolle."],
    riskSense: ["Sehr geringes Risikoempfinden: Gefahr von Sorglosigkeit oder Shadow-Use.", "Geringes Risikoempfinden: Risiken müssen sichtbar gemacht werden.", "Mittleres Risikoempfinden: abwägende Haltung möglich.", "Hohes Risikoempfinden: Schutz-, Datenschutz- oder Qualitätsfragen dominieren.", "Sehr hohes Risikoempfinden: wertvolle Frühwarnrolle oder Blockadepunkt."],
    changeEnergy: ["Sehr geringe Veränderungsenergie: passive oder blockierende Dynamik möglich.", "Geringe Veränderungsenergie: Beteiligung braucht Entlastung und Sinn.", "Mittlere Veränderungsenergie: Mitgehen möglich, wenn Aufwand und Nutzen plausibel sind.", "Hohe Veränderungsenergie: kann Umsetzung aktiv unterstützen.", "Sehr hohe Veränderungsenergie: mögliche Treiber- oder Pilotrolle."],
    current: ["Sehr schwach ausgeprägt: akuter Stabilisierungsbedarf.", "Schwach ausgeprägt: Ressource ist fragil.", "Mittel ausgeprägt: tragfähig, aber beobachtungsbedürftig.", "Gut ausgeprägt: Ressource kann genutzt werden.", "Sehr stark ausgeprägt: Ressource ist ein Hebel im Szenario."],
    target: ["Minimalziel: nur basale Stabilisierung nötig.", "Niedriges Ziel: begrenzte Verbesserung reicht.", "Mittleres Ziel: solide Arbeitsfähigkeit wird angestrebt.", "Hohes Ziel: Ressource soll aktiv tragend werden.", "Sehr hohes Ziel: Ressource wird zentraler Erfolgsfaktor."],
    speed: ["Sehr langsam: lange Klärung vor Bewegung.", "Eher langsam: Sorgfalt und Beteiligung bremsen, erhöhen aber Anschlussfähigkeit.", "Mittleres Tempo: Klärung und Umsetzung halten sich die Waage.", "Eher schnell: rascher Start mit Kommunikationsbedarf.", "Sehr schnell: hoher Umsetzungsschub durch klare Entscheidung."],
    acceptance: ["Sehr geringe Akzeptanz: Vorgehen wirkt fremd oder belastend.", "Geringe Akzeptanz: Beteiligungs- und Vertrauensrisiken.", "Mittlere Akzeptanz: Zustimmung hängt stark von Kommunikation ab.", "Hohe Akzeptanz: anschlussfähig, wenn Grenzen klar bleiben.", "Sehr hohe Akzeptanz: passt gut zu Bedarf und Belastungslage."],
    control: ["Sehr geringe Kontrolle: Governance kaum steuerbar.", "Geringe Kontrolle: relevante Lücken und Nachsteuerungsbedarf.", "Mittlere Kontrolle: Grundregeln möglich, aber nicht vollständig abgesichert.", "Hohe Kontrolle: Zuständigkeiten und Datenregeln gut steuerbar.", "Sehr hohe Kontrolle: Governance und Qualitätssicherung klar angelegt."],
    innovation: ["Sehr gering: Lernen und Erprobung stark begrenzt.", "Gering: wenige neue Praxisimpulse.", "Mittel: Raum für Lernen, aber keine breite Erprobung.", "Hoch: praxisnahe Experimente wahrscheinlich.", "Sehr hoch: viele Use Cases und organisationales Lernen."],
    risk: ["Sehr gering: wenige erkennbare Nebenwirkungen.", "Gering: wichtigste Risiken wirken beherrschbar.", "Mittel: Nebenwirkungen müssen aktiv moderiert werden.", "Hoch: Widerstand oder Governance-Probleme wahrscheinlich.", "Sehr hoch: Vertrauen, Beteiligung oder Datenschutz können destabilisiert werden."]
  };
  return data[kind]?.[i] || "Bitte fachlich einordnen.";
}
function explainChoice(kind, value) {
  const data = {
    evidence: { niedrig: "Kaum belegt. Vor Entscheidung validieren.", mittel: "Plausibel, aber prüfbedürftig.", hoch: "Gut beobachtet oder durch mehrere Hinweise gestützt." },
    uncertainty: { niedrig: "Annahme ist relativ stabil.", mittel: "Annahme kann zutreffen, sollte aber beobachtet werden.", hoch: "Hohe Unsicherheit. Simulation stark abhängig von dieser Annahme." },
    sensitivity: { unkritisch: "Keine besondere Schutzbedürftigkeit erkennbar.", intern: "Nur intern verwenden.", vertraulich: "Vertraulich behandeln und sparsam speichern.", "personenbezogen vermeiden": "Nicht als personenbezogenes Profil verwenden; anonymisieren." },
    sourceStatus: { explizit: "Im Dokument oder Auftrag ausdrücklich genannt.", abgeleitet: "Aus Kontext oder Struktur erschlossen.", Hypothese: "Beratungshypothese; unbedingt prüfen." },
    direction: { high_good: "Je höher der Wert, desto stabiler die Ressource.", low_good: "Je niedriger der Wert, desto besser. Beispiel: Zeitdruck oder Konfliktspannung." },
    trend: { steigend: "Entwickelt sich nach oben.", stabil: "Bleibt derzeit ungefähr gleich.", fallend: "Schwächt sich ab.", unklar: "Noch nicht ausreichend einschätzbar." },
    effort: { niedrig: "Mit wenig Aufwand umsetzbar.", mittel: "Benötigt Vorbereitung oder Abstimmung.", hoch: "Erfordert deutliche Ressourcen, Zeit oder Mandat." }
  };
  return data[kind]?.[value] || "Bitte fachlich prüfen und bei Bedarf überschreiben.";
}

function assumption(text, source = "Vorlage", evidence = "mittel", uncertainty = "mittel", sensitivity = "intern", sourceStatus = "abgeleitet") {
  return { id: uid(), text, source, evidence, evidenceText: explainChoice("evidence", evidence), uncertainty, uncertaintyText: explainChoice("uncertainty", uncertainty), sensitivity, sensitivityText: explainChoice("sensitivity", sensitivity), sourceStatus, sourceStatusText: explainChoice("sourceStatus", sourceStatus) };
}
function persona(name, role, stance, influence, affectedness, trust, aiLiteracy, riskSense, changeEnergy, informalRole, conflictStyle, trigger, learningNeed, communicationNeed) {
  return { id: uid(), name, role, stance, influence, influenceText: explain("influence", influence), affectedness, affectednessText: explain("affectedness", affectedness), trust, trustText: explain("trust", trust), aiLiteracy, aiLiteracyText: explain("aiLiteracy", aiLiteracy), riskSense, riskSenseText: explain("riskSense", riskSense), changeEnergy, changeEnergyText: explain("changeEnergy", changeEnergy), informalRole, conflictStyle, trigger, learningNeed, communicationNeed };
}
function resource(name, type, current, target, direction, trend, bottleneck, owner) {
  return { id: uid(), name, type, current, currentText: explain("current", current), target, targetText: explain("target", target), direction, directionText: explainChoice("direction", direction), trend, trendText: explainChoice("trend", trend), bottleneck, owner };
}
function intervention(name, timing, target, benefit, sideEffect, effort) {
  return { id: uid(), name, timing, timingText: `Intervention im Abschnitt „${timing}“ einplanen und mit Ziel sowie Nebenwirkung prüfen.`, target, benefit, sideEffect, effort, effortText: explainChoice("effort", effort) };
}
function strategy(name, description, speed, acceptance, control, innovation, risk, conditions, failureMode, decisionSignal) {
  return { id: uid(), name, description, speed, speedText: explain("speed", speed), acceptance, acceptanceText: explain("acceptance", acceptance), control, controlText: explain("control", control), innovation, innovationText: explain("innovation", innovation), risk, riskText: explain("risk", risk), conditions, failureMode, decisionSignal };
}
